  quack(): void;
  walk(): void;
}

class MallardDuck implements Duck {
  quack(): void {
    console.log("Quack!");
  }

  walk(): void {
    console.log("Walking...");
  }
}

class Person {
  quack(): void {
    console.log("I'm quacking like a duck!");
  }

  walk(): void {
    console.log("I'm walking...");
  }
}

